void run(OverloadCoffee receiver, String label, Object unknown) {
        receiver.pour("espresso");
        receiver.pour(2);
        receiver.pour(label);
        receiver.pour(unknown);
        receiver.count();
        receiver.count(1);
        receiver.count(1, 2);
        receiver.batch("coffee", 1, 2);
        receiver.uncertain("coffee");
        receiver.generic("coffee");
        receiver.numeric(1);
        receiver.batch("coffee");
